// Graph managedDevice-Felder auf Tabellenspalten von public.intune_devices mappen.
// Bekannte Datengrenze: processorArchitecture ist im v1.0-Endpoint das einzige
// CPU-Feld (kein Modell/Kernanzahl), siehe docs/28_intune_inventory.md.
const KNOWN_FIELDS = new Set([
  'id', 'deviceName', 'operatingSystem', 'osVersion', 'model', 'manufacturer',
  'physicalMemoryInBytes', 'processorArchitecture', 'userPrincipalName',
  'userDisplayName', 'complianceState', 'lastSyncDateTime'
]);

return $input.all().map(item => {
  const d = item.json;
  const rawMetadata = Object.fromEntries(
    Object.entries(d).filter(([key]) => !KNOWN_FIELDS.has(key))
  );

  return {
    json: {
      intune_device_id: d.id,
      device_name: d.deviceName || null,
      operating_system: d.operatingSystem || null,
      os_version: d.osVersion || null,
      model: d.model || null,
      manufacturer: d.manufacturer || null,
      physical_memory_bytes: d.physicalMemoryInBytes ?? null,
      processor_architecture: d.processorArchitecture || null,
      primary_user_upn: d.userPrincipalName || null,
      primary_user_display_name: d.userDisplayName || null,
      compliance_state: d.complianceState || null,
      last_sync_date_time: d.lastSyncDateTime || null,
      raw_metadata: JSON.stringify(rawMetadata),
      synced_at: new Date().toISOString()
    }
  };
});
